(() => {
  const CSS = `
.ed-editor{position:relative;font:16px/1.65 var(--font-ui);color:var(--ink,#37352f);padding:5px 0 100px;min-height:180px}.ed-block{position:relative;min-height:30px;margin:2px 0;display:flex;align-items:flex-start;gap:8px;border-radius:3px}.ed-block.ed-dragging{opacity:.45}.ed-controls{position:absolute;left:-48px;top:3px;display:flex;gap:0;opacity:0;transition:opacity .1s}.ed-block:hover>.ed-controls,.ed-block:focus-within>.ed-controls{opacity:1}.ed-control{width:23px;height:26px;padding:0!important;display:grid;place-items:center;border:0;background:transparent;color:#9b9a97;cursor:pointer;font:20px/1 Arial;border-radius:3px}.ed-control:hover{background:var(--hover,#efefed);color:var(--ink,#37352f)}.ed-handle{font-size:17px;letter-spacing:-3px;cursor:grab}.ed-content{outline:none;flex:1;min-width:0;min-height:27px;white-space:pre-wrap;overflow-wrap:anywhere;border-radius:3px}.ed-content:empty:before{content:attr(data-placeholder);color:#aaa9a6;pointer-events:none}.ed-h1{margin-top:24px}.ed-h1 .ed-content{font-size:29px;font-weight:650;line-height:1.35;letter-spacing:-.55px}.ed-h2{margin-top:19px}.ed-h2 .ed-content{font-size:23px;font-weight:650;line-height:1.45;letter-spacing:-.3px}.ed-h3{margin-top:14px}.ed-h3 .ed-content{font-size:19px;font-weight:650;line-height:1.5}.ed-prefix{flex:none;width:19px;text-align:center;line-height:27px;user-select:none}.ed-todo input{margin:6px 1px 0;width:16px;height:16px;accent-color:#2383e2;flex:none;cursor:pointer}.ed-done .ed-content{text-decoration:line-through;color:#9b9a97}.ed-quote{border-left:3px solid currentColor;padding:1px 0 1px 15px;margin:10px 0}.ed-callout{background:var(--panel,#f5f5f3);border-radius:4px;padding:15px 17px;margin:12px 0;gap:12px}.ed-callout .ed-controls{top:15px}.ed-code{background:var(--panel,#f7f6f3);border-radius:4px;padding:24px 20px;margin:12px 0}.ed-code .ed-content{font:13px/1.7 var(--font-mono)}.ed-code:before{content:'Plain text';position:absolute;right:13px;top:3px;font-size:10px;color:#9b9a97}.ed-divider{padding:12px 0;min-height:27px}.ed-divider hr{border:0;border-top:1px solid var(--border,#e9e9e7);width:100%;margin:0}.ed-toggle-button{border:0;background:transparent;color:inherit;padding:2px 0;cursor:pointer;line-height:25px;width:19px}.ed-toggle .ed-content{margin-left:0}.ed-toggle{flex-wrap:wrap;column-gap:8px;row-gap:0}.ed-toggle>.ed-content{flex-basis:calc(100% - 27px)}.ed-toggle-details{margin:2px 0 4px 27px;flex-basis:calc(100% - 27px);outline:none;min-height:27px;white-space:pre-wrap}.ed-toggle-details:empty:before{content:attr(data-placeholder);color:#aaa9a6}.ed-toggle.ed-folded>.ed-toggle-details{display:none}.ed-block code{font:85% var(--font-mono);background:#f1f1ef;color:#eb5757;padding:2px 4px;border-radius:3px}.ed-link .ed-content{text-decoration:underline;text-decoration-color:#ccc;text-underline-offset:3px}.ed-menu{position:fixed;z-index:400;background:var(--surface,#fff);color:var(--ink,#37352f);border:1px solid var(--border,#e9e9e7);border-radius:7px;box-shadow:0 5px 20px #0002,0 0 1px #0002;padding:5px;min-width:235px;max-width:310px;max-height:360px;overflow:auto;font:14px/1.4 var(--font-ui)}.ed-menu-title{padding:8px 9px 5px;color:#9b9a97;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.4px}.ed-menu-item{display:flex;align-items:center;gap:11px;padding:7px 9px;border-radius:4px;cursor:pointer;width:100%;border:0;background:transparent;color:inherit;text-align:left;font:inherit}.ed-menu-item:hover,.ed-menu-item.ed-selected{background:var(--hover,#f1f1ef)}.ed-menu-icon{height:31px;min-width:31px;border:1px solid var(--border,#e9e9e7);border-radius:4px;display:grid;place-items:center;background:var(--surface,#fff);font-size:18px}.ed-menu-copy{display:flex;flex-direction:column}.ed-menu-copy small{font-size:11px;color:#9b9a97}.ed-menu-separator{height:1px;background:var(--border,#e9e9e7);margin:5px -5px}.ed-empty-add{color:#aaa9a6;cursor:text;padding:4px 0}.ed-toolbar{position:fixed;z-index:450;display:flex;background:var(--surface,#fff);border:1px solid var(--border,#e9e9e7);border-radius:5px;box-shadow:0 4px 15px #0002;padding:3px}.ed-toolbar button{font-family:inherit;font-size:14px;line-height:1.4;background:none;border:0;border-radius:3px;height:29px;min-width:31px;color:inherit;cursor:pointer}.ed-toolbar button:hover{background:var(--hover,#eee)}.ed-toolbar button+button{border-left:1px solid var(--border,#eee)}@media(max-width:650px){.ed-controls{left:-27px}.ed-control:first-child{display:none}.ed-editor{font-size:15px}.ed-menu{max-width:calc(100vw - 25px)}}`;
  const style = document.createElement('style');style.textContent=CSS;document.head.appendChild(style);
  const types = [
    ['text','Text','Just start writing with plain text.','T'],['h1','Heading 1','Big section heading.','H₁'],['h2','Heading 2','Medium section heading.','H₂'],['h3','Heading 3','Small section heading.','H₃'],['todo','To-do list','Track tasks with a to-do list.','☑'],['bullet','Bulleted list','Create a simple bulleted list.','•'],['number','Numbered list','Create a list with numbering.','1.'],['toggle','Toggle list','A collapsible block.','▸'],['quote','Quote','Capture a quote.','“'],['callout','Callout','Make something stand out.','💡'],['code','Code','Capture a code snippet.','‹›'],['divider','Divider','Visually divide blocks.','—'],['link','Page link','Link to another page.','↗']
  ];
  const uid=()=>Math.random().toString(36).slice(2,10);
  const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const cleanHTML=html=>{const d=document.createElement('div');d.innerHTML=html;d.querySelectorAll('*').forEach(el=>{if(!['B','STRONG','I','EM','U','S','STRIKE','CODE','BR','A','SPAN'].includes(el.tagName)){el.replaceWith(...el.childNodes);return}for(const a of [...el.attributes])el.removeAttribute(a.name)});return d.innerHTML};
  let cleanup=()=>{};
  window.Editor={render(container,page,onChange=()=>{}){
    cleanup();
    let blocks=(page.blocks?.length?page.blocks:[{id:uid(),type:'text',text:''}]).map(b=>({...b,id:b.id||uid()}));
    const root=document.createElement('div');root.className='ed-editor';container.replaceChildren(root);
    let menu=null,toolbar=null,slash=null,selected=0;
    const emit=()=>{page.blocks=blocks;onChange(blocks.map(b=>({...b})))};
    const getBlock=id=>blocks.find(b=>b.id===id);
    const getEl=id=>root.querySelector(`[data-block-id="${id}"] .ed-content`);
    const focus=(id,end=true)=>{const el=getEl(id);if(!el)return;el.focus();const r=document.createRange();r.selectNodeContents(el);r.collapse(!end);const s=getSelection();s.removeAllRanges();s.addRange(r)};
    const closeMenu=()=>{menu?.remove();menu=null;slash=null;selected=0};
    const closeToolbar=()=>{toolbar?.remove();toolbar=null};
    const position=(el,rect)=>{el.style.left=Math.max(8,Math.min(rect.left,innerWidth-el.offsetWidth-12))+'px';el.style.top=Math.min(rect.bottom+5,innerHeight-el.offsetHeight-12)+'px'};
    const saveNode=(el,b)=>{if(!root.contains(el))return;b.text=el.innerText.replace(/\n$/,'');b.html=cleanHTML(el.innerHTML);emit()};
    const insertAfter=(id,type='text')=>{const index=blocks.findIndex(b=>b.id===id);const b={id:uid(),type,text:''};blocks.splice(index+1,0,b);emit();paint();focus(b.id);return b};
    const setType=(b,type)=>{b.type=type;b.text=b.text.replace(/^\/[^\n]*/,'');delete b.html;closeMenu();emit();paint();focus(b.id)};
    const deleteBlock=b=>{const n=blocks.indexOf(b);blocks.splice(n,1);if(!blocks.length)blocks.push({id:uid(),type:'text',text:''});closeMenu();emit();paint();focus(blocks[Math.max(0,n-1)].id)};
    const openMenu=(rect,items,title='Basic blocks')=>{closeMenu();menu=document.createElement('div');menu.className='ed-menu';if(title){const t=document.createElement('div');t.className='ed-menu-title';t.textContent=title;menu.append(t)}items.forEach((item,i)=>{if(item.separator){const hr=document.createElement('div');hr.className='ed-menu-separator';menu.append(hr);return}const row=document.createElement('button');row.className='ed-menu-item';row.dataset.menuIndex=i;row.innerHTML=`<span class="ed-menu-icon">${escape(item.icon||'⋮')}</span><span class="ed-menu-copy">${escape(item.name)}${item.description?`<small>${escape(item.description)}</small>`:''}</span>`;row.addEventListener('mousedown',e=>{e.preventDefault();item.action()});menu.append(row)});document.body.append(menu);position(menu,rect);return menu};
    const showSlash=(b,el,query='')=>{const items=types.filter(t=>(t[1]+' '+t[0]).toLowerCase().includes(query.toLowerCase())).map(t=>({name:t[1],description:t[2],icon:t[3],action:()=>setType(b,t[0])}));const rect=el.getBoundingClientRect();openMenu(rect,items,items.length?'Basic blocks':'No matching blocks');slash={block:b,items};selected=0;menu.querySelector('.ed-menu-item')?.classList.add('ed-selected')};
    const blockMenu=(b,button)=>openMenu(button.getBoundingClientRect(),[
      {name:'Turn into',description:'Choose another block type',icon:'↻',action:()=>{openMenu(button.getBoundingClientRect(),types.map(t=>({name:t[1],icon:t[3],action:()=>setType(b,t[0])}))) }},
      {name:'Duplicate',icon:'⧉',action:()=>{const n=blocks.indexOf(b),copy={...b,id:uid()};blocks.splice(n+1,0,copy);closeMenu();emit();paint();focus(copy.id)}},
      {name:'Move up',icon:'↑',action:()=>{const n=blocks.indexOf(b);if(n>0){[blocks[n-1],blocks[n]]=[blocks[n],blocks[n-1]];emit();paint()}closeMenu()}},
      {name:'Move down',icon:'↓',action:()=>{const n=blocks.indexOf(b);if(n<blocks.length-1){[blocks[n+1],blocks[n]]=[blocks[n],blocks[n+1]];emit();paint()}closeMenu()}},
      {name:'Delete',icon:'⌫',action:()=>deleteBlock(b)}
    ],'Block actions');
    function paint(){
      closeToolbar();root.replaceChildren();let number=0;
      blocks.forEach((b,index)=>{
        const type=b.type==='paragraph'?'text':b.type==='heading1'?'h1':b.type==='heading2'?'h2':b.type==='heading3'?'h3':b.type==='bulleted-list'?'bullet':b.type;
        if(type==='number')number++;else number=0;
        const row=document.createElement('div');row.className=`ed-block ed-${type}${b.checked?' ed-done':''}${b.folded?' ed-folded':''}`;row.dataset.blockId=b.id;
        const controls=document.createElement('div');controls.className='ed-controls';controls.innerHTML='<button class="ed-control" type="button" title="Add a block" aria-label="Add a block">+</button><button class="ed-control ed-handle" type="button" title="Block actions" aria-label="Block actions">⠿</button>';row.append(controls);
        controls.children[0].addEventListener('click',()=>{const next=insertAfter(b.id);const el=getEl(next.id);showSlash(next,el)});controls.children[1].addEventListener('click',()=>blockMenu(b,controls.children[1]));
        if(type==='divider'){const hr=document.createElement('hr');row.append(hr);row.tabIndex=0;row.addEventListener('keydown',e=>{if(e.key==='Backspace'){e.preventDefault();deleteBlock(b)}if(e.key==='Enter'){e.preventDefault();insertAfter(b.id)}});root.append(row);return}
        if(type==='todo'){const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=!!b.checked;checkbox.setAttribute('aria-label','Complete task');checkbox.addEventListener('change',()=>{b.checked=checkbox.checked;row.classList.toggle('ed-done',b.checked);emit()});row.append(checkbox)}
        if(['bullet','number','callout','quote','link'].includes(type)&&type!=='quote'){const prefix=document.createElement('span');prefix.className='ed-prefix';prefix.textContent=type==='bullet'?'•':type==='number'?number+'.':type==='callout'?'💡':'↗';row.append(prefix)}
        if(type==='toggle'){const toggle=document.createElement('button');toggle.type='button';toggle.className='ed-toggle-button';toggle.textContent=b.folded?'▸':'▾';toggle.setAttribute('aria-label','Toggle block');toggle.setAttribute('aria-expanded',String(!b.folded));toggle.addEventListener('click',()=>{b.folded=!b.folded;toggle.textContent=b.folded?'▸':'▾';toggle.setAttribute('aria-expanded',String(!b.folded));row.classList.toggle('ed-folded',b.folded);emit()});row.append(toggle)}
        const el=document.createElement('div');el.className='ed-content';el.contentEditable='true';el.spellcheck=true;el.setAttribute('role','textbox');el.setAttribute('aria-multiline','true');el.dataset.placeholder=type==='code'?'Type code…':type==='h1'?'Heading 1':type==='h2'?'Heading 2':type==='h3'?'Heading 3':type==='todo'?'To-do':"Type '/' for commands";
        if(b.html)el.innerHTML=cleanHTML(b.html);else el.textContent=b.text||'';
        el.addEventListener('input',()=>{saveNode(el,b);const text=el.innerText;if(text.startsWith('/')&&!text.includes('\n'))showSlash(b,el,text.slice(1));else if(slash?.block===b)closeMenu();if(text==='---'){b.type='divider';b.text='';delete b.html;emit();paint();insertAfter(b.id)}const shortcuts={'# ':'h1','## ':'h2','### ':'h3','- ':'bullet','* ':'bullet','1. ':'number','[] ':'todo','> ':'quote'};if(shortcuts[text]){b.text='';delete b.html;setType(b,shortcuts[text])}});
        el.addEventListener('keydown',e=>{
          if(slash?.block===b&&['ArrowDown','ArrowUp','Enter','Escape'].includes(e.key)){e.preventDefault();if(e.key==='Escape')closeMenu();else if(e.key==='Enter'){slash.items[selected]?.action()}else{const len=slash.items.length;if(len){selected=(selected+(e.key==='ArrowDown'?1:-1)+len)%len;menu.querySelectorAll('.ed-menu-item').forEach((r,i)=>r.classList.toggle('ed-selected',i===selected));menu.querySelector('.ed-selected')?.scrollIntoView({block:'nearest'})}}return}
          if(e.key==='Enter'&&!e.shiftKey&&type!=='code'){e.preventDefault();saveNode(el,b);const selection=getSelection();let trailing='';if(selection.rangeCount&&el.contains(selection.anchorNode)){const range=selection.getRangeAt(0);const tail=range.cloneRange();tail.setEndAfter(el.lastChild||el);if(el.lastChild){try{tail.setEnd(el,el.childNodes.length);trailing=tail.toString();tail.deleteContents();b.text=el.innerText;b.html=cleanHTML(el.innerHTML)}catch{}}}const nextType=['bullet','number','todo'].includes(type)&&b.text?type:'text';const next={id:uid(),type:nextType,text:trailing};if(!b.text&&['bullet','number','todo'].includes(type)){b.type='text';delete b.html;emit();paint();focus(b.id)}else{blocks.splice(index+1,0,next);emit();paint();focus(next.id,false)}}
          if(e.key==='Backspace'&&!el.innerText){e.preventDefault();if(type!=='text'){setType(b,'text')}else if(blocks.length>1)deleteBlock(b)}
          if((e.metaKey||e.ctrlKey)&&e.key==='d'){e.preventDefault();const copy={...b,id:uid()};blocks.splice(index+1,0,copy);emit();paint();focus(copy.id)}
        });
        el.addEventListener('paste',e=>{e.preventDefault();const text=e.clipboardData.getData('text/plain');document.execCommand('insertText',false,text);saveNode(el,b)});
        el.addEventListener('blur',()=>saveNode(el,b));row.append(el);if(type==='toggle'){const details=document.createElement('div');details.className='ed-toggle-details';details.contentEditable='true';details.dataset.placeholder='Empty toggle. Click to write something…';details.setAttribute('role','textbox');details.setAttribute('aria-label','Toggle content');details.textContent=b.details||'';details.addEventListener('input',()=>{b.details=details.innerText;emit()});details.addEventListener('paste',e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'))});row.append(details)}root.append(row);
      });
      const add=document.createElement('div');add.className='ed-empty-add';add.textContent='';add.style.minHeight='60px';add.addEventListener('click',()=>{const last=blocks[blocks.length-1];if(last.type==='text'&&!last.text)focus(last.id);else insertAfter(last.id)});root.append(add);
    }
    const onDown=e=>{if(menu&&!menu.contains(e.target)&&!e.target.closest('.ed-control'))closeMenu();if(toolbar&&!toolbar.contains(e.target)&&!root.contains(e.target))closeToolbar()};
    const onKey=e=>{if(e.key==='Escape'){closeMenu();closeToolbar()}};
    const onUp=e=>{if(toolbar?.contains(e.target))return;setTimeout(()=>{const s=getSelection();if(!s||s.isCollapsed||!root.contains(s.anchorNode)||!root.contains(s.focusNode)){closeToolbar();return}const range=s.getRangeAt(0).cloneRange(),rect=range.getBoundingClientRect();closeToolbar();toolbar=document.createElement('div');toolbar.className='ed-toolbar';[['bold','B'],['italic','𝘐'],['underline','U'],['strikeThrough','S'],['code','‹›']].forEach(([command,label])=>{const button=document.createElement('button');button.type='button';button.title=command==='code'?'Inline code':command;button.setAttribute('aria-label',button.title);button.textContent=label;button.addEventListener('mousedown',event=>{event.preventDefault();s.removeAllRanges();s.addRange(range);if(command==='code'){const code=document.createElement('code');try{range.surroundContents(code)}catch{document.execCommand('insertHTML',false,`<code>${escape(s.toString())}</code>`)}}else document.execCommand(command);const el=s.anchorNode?.parentElement?.closest('.ed-content');if(el){const b=getBlock(el.closest('.ed-block').dataset.blockId);saveNode(el,b)}closeToolbar()});toolbar.append(button)});document.body.append(toolbar);position(toolbar,{left:rect.left,bottom:rect.top-45})},0)};
    document.addEventListener('mousedown',onDown);document.addEventListener('keydown',onKey);document.addEventListener('mouseup',onUp);paint();
    cleanup=()=>{closeMenu();closeToolbar();document.removeEventListener('mousedown',onDown);document.removeEventListener('keydown',onKey);document.removeEventListener('mouseup',onUp)};
    return {getBlocks:()=>blocks,focus:()=>focus(blocks[0].id),destroy:cleanup};
  }};
})();
